const tipoCliente = $('When Executed by Another Workflow').first().json.tipo_cliente;
const busqueda = ($('When Executed by Another Workflow').first().json.busqueda || '').trim().toLowerCase();
const terminos = busqueda ? busqueda.split(/\s+/).filter(Boolean) : [];
const items = $input.all();
const result = [];
for (const item of items) {
  if (terminos.length) {
    const marca = (item.json.MARCA || '').toLowerCase();
    const modelo = (item.json.MODELO || '').toLowerCase();
    const combinado = marca + ' ' + modelo;
    const matchTodos = terminos.every(t => combinado.includes(t));
    if (!matchTodos) continue;
  }
  const precio = tipoCliente === 'mayorista' ? item.json.PRECIO_MAYORISTA : item.json.PRECIO_MINORISTA;
  const nuevo = Object.assign({}, item.json);
  nuevo.PRECIO = precio;
  delete nuevo.PRECIO_MAYORISTA;
  delete nuevo.PRECIO_MINORISTA;
  result.push({ json: nuevo });
}
if (result.length === 0) {
  return [{ json: { sin_resultados: true, mensaje: "No se encontraron paletas en stock que coincidan con la busqueda." } }];
}
return result;
